import { Prisma } from '@prisma/client';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import type { ArticleWithRelations } from '../serializers/index.js';
import type { ViewerId } from '../types.js';

/**
 * viewerId 기준 favorited/following 계산을 위한 Prisma include 객체.
 *
 * 관계를 viewer로 좁혀 로드한 뒤 배열 길이로 판단하므로 목록 조회에서도 N+1이
 * 생기지 않는다. 익명(viewerId === null)이면 두 관계를 아예 싣지 않고
 * `normalizeArticle`이 빈 배열로 채운다.
 */
export function articleInclude(viewerId: ViewerId): object {
  return {
    author: {
      select: {
        username: true,
        bio: true,
        image: true,
        ...(viewerId !== null && {
          followers: { where: { followerId: viewerId }, select: { followerId: true } },
        }),
      },
    },
    // 태그는 입력 순서(order) 오름차순 그대로. 알파벳 정렬 금지.
    tags: { select: { order: true, tag: { select: { name: true } } }, orderBy: { order: 'asc' } },
    _count: { select: { favorites: true } },
    ...(viewerId !== null && {
      favorites: { where: { userId: viewerId }, select: { userId: true } },
    }),
  };
}

/** `articleInclude`가 `object`를 반환하므로 Prisma 인자로 넘길 때 이 캐스트를 쓴다. */
export function asArticleInclude(viewerId: ViewerId): Prisma.ArticleInclude {
  return articleInclude(viewerId) as Prisma.ArticleInclude;
}

/** articleInclude로 조회한 raw 레코드를 ArticleWithRelations 형태로 정규화. */
export function normalizeArticle(raw: any): ArticleWithRelations {
  const { followers, username, bio, image } = raw.author;

  return {
    slug: raw.slug,
    title: raw.title,
    description: raw.description,
    body: raw.body,
    createdAt: raw.createdAt,
    updatedAt: raw.updatedAt,
    author: { username, bio: bio ?? null, image: image ?? null },
    tags: raw.tags,
    _count: raw._count,
    favorites: raw.favorites ?? [],
    authorFollowedBy: followers ?? [],
  };
}

export type ListParams = {
  where: object;
  viewerId: ViewerId;
  limit: number;
  offset: number;
};

/**
 * 목록/피드 공용 조회. 태스크 10의 feed도 `where`만 바꿔 재사용한다.
 *
 * `articlesCount`는 skip/take를 적용하지 않은 동일 `where`로 따로 센다.
 * `limit=1`이어도 조건에 맞는 전체 건수가 나와야 pagination.hurl이 통과한다.
 */
export async function listArticles(
  p: ListParams,
): Promise<{ items: ArticleWithRelations[]; articlesCount: number }> {
  const where = p.where as Prisma.ArticleWhereInput;

  const [raws, articlesCount] = await Promise.all([
    prisma.article.findMany({
      where,
      include: asArticleInclude(p.viewerId),
      // 같은 밀리초에 만들어진 글의 순서가 흔들리지 않도록 id로 보조 정렬한다.
      orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
      skip: p.offset,
      take: p.limit,
    }),
    prisma.article.count({ where }),
  ]);

  return { items: raws.map(normalizeArticle), articlesCount };
}

/** slug로 조회. 없으면 404 `{"errors":{"article":["not found"]}}`. */
export async function findArticleOr404(
  slug: string,
  viewerId: ViewerId,
): Promise<ArticleWithRelations> {
  const raw = await prisma.article.findUnique({
    where: { slug },
    include: asArticleInclude(viewerId),
  });
  if (raw === null) throw ApiError.notFound('article');
  return normalizeArticle(raw);
}

