function articlePayload(body: unknown): Record<string, unknown> {
  if (typeof body !== 'object' || body === null) return {};
  const article = (body as Record<string, unknown>).article;
  if (typeof article !== 'object' || article === null) return {};
  return article as Record<string, unknown>;
}

