        ...(favorited !== undefined && { favorites: { some: { user: { username: favorited } } } }),
      };

      const { items, articlesCount } = await listArticles({
        where,
        viewerId: req.userId,
        limit: intOr(req.query.limit, 20),
        offset: intOr(req.query.offset, 0),
      });
      return toArticlesResponse(items, articlesCount);
    },
  );

  app.post('/articles', { preHandler: requireAuth }, async (req, reply) => {
    const payload = articlePayload(req.body);
    const title = requireText(payload, 'title');
    const description = requireText(payload, 'description');
    const body = requireText(payload, 'body');
