  );

  app.put<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req) => {
      const userId = req.userId!;
      const existing = await findOwnArticleOr40x(req.params.slug, userId);

      const payload = articlePayload(req.body);
      // slug는 title이 바뀌어도 유지한다.
      const data: Prisma.ArticleUpdateInput = {};
      for (const field of TEXT_FIELDS) {
        if (Object.hasOwn(payload, field)) data[field] = requireText(payload, field);
