      const tags = parseTagList(payload);

      // @updatedAt은 스칼라가 실제로 바뀔 때만 갱신되므로 명시적으로 넣는다.
      data.updatedAt = new Date();

      await prisma.$transaction(async (tx) => {
        // tagList 키가 없으면 기존 태그 유지, []면 전체 삭제, 배열이면 순서 그대로 교체.
        if (tags !== undefined) {
          await tx.articleTag.deleteMany({ where: { articleId: existing.id } });
          data.tags = { create: tagCreateInput(tags) };
        }
        await tx.article.update({ where: { id: existing.id }, data });
      });

      return toArticleResponse(await findArticleOr404(req.params.slug, userId));
    },
  );

  app.delete<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req, reply) => {
      const existing = await findOwnArticleOr40x(req.params.slug, req.userId!);
      await prisma.article.delete({ where: { id: existing.id } });
      return reply.code(204).send();
    },
  );
};

